            const response = { type: request.inputType, value: version }
            await bridge.answerActionInput(request.runId, response)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not submit version' })
        }
    }

    useEffect(() => {
        const handleWindowClose = () => { void getElectronActionBridge()?.cancelActionRun(request.runId) }
        window.addEventListener('beforeunload', handleWindowClose)

        return () => window.removeEventListener('beforeunload', handleWindowClose)
    }, [request.runId])

    return (
        <Dialog fullWidth maxWidth="xs" onClose={handleCancel} open>
            <DialogTitle>{request.prompt}</DialogTitle>
            <DialogContent>
                <TextField autoFocus fullWidth label="Version" onChange={handleChange} size="small" value={version} />
            </DialogContent>
            <DialogActions>
                <Button onClick={handleCancel}>Cancel</Button>
                <Button disabled={version.trim().length === 0} onClick={handleConfirm} variant="contained">Confirm</Button>
            </DialogActions>
        </Dialog>
    )
}

/** Shows oldest pending run request; later requests wait their turn. */
export function ActionVersionDialog() {
    const requests = useSyncExternalStore(actionVersionRequestService.subscribe, actionVersionRequestService.getSnapshot)
    const request = requests[0]

    return request ? <PendingVersionDialog key={request.runId} request={request} /> : null
}

import { Button, Stack, Typography } from '@mui/material'
import type { ActionScheduleAccountTracker, ActionScheduleCardOption } from './action_schedule_options'
import type { ActionScheduleSnapshot, ActionScheduleTriggerType } from './action_schedule_store'
import type { AgentAccount } from '../../../../data/agent_accounts'
import { ScheduleTriggerFields, type ScheduleTriggerFieldsChange } from './schedule_trigger_fields'

export type ActionScheduleFormChange =
    | { accountId: string; type: 'account' }
    | { agent: string; type: 'agent' }
    | { cardInternalId: string; type: 'card' }
    | { limitId: string; type: 'tracker'; windowId: string }
    | { targetState: string; type: 'target-state' }
    | { timestamp: string; type: 'timestamp' }
    | { triggerType: ActionScheduleTriggerType; type: 'trigger-type' }

interface ActionScheduleFormProps {
    accounts: AgentAccount[]
    accountTrackers: ActionScheduleAccountTracker[]
    canRegister: boolean
    cards: ActionScheduleCardOption[]
    message: string | null
    onChange(change: ActionScheduleFormChange): void
    onRegister(): void
    snapshot: ActionScheduleSnapshot
    targetStates: string[]
}

/** Trigger selection and trigger-specific schedule fields. */
export function ActionScheduleForm(props: ActionScheduleFormProps) {
    const { accounts, accountTrackers, canRegister, cards, message, onChange, onRegister, snapshot, targetStates } = props
    const handleChange = (change: ScheduleTriggerFieldsChange) => {
        if (change.type === 'trigger-type' && change.triggerType === 'now') return
        onChange(change as ActionScheduleFormChange)
    }

    return (
        <Stack spacing={1.5}>
            <ScheduleTriggerFields
                accountTrackers={accountTrackers}
                accounts={accounts}
                cards={cards}
                onChange={handleChange}
                snapshot={snapshot}
                targetStates={targetStates}
            />
            <Button disabled={!canRegister} onClick={onRegister} size="small" variant="contained">Schedule action</Button>
            {message ? <Typography color="text.secondary" role="status" variant="caption">{message}</Typography> : null}
        </Stack>
    )
}
